# Cleaning Pipeline v1 — Session 04 (26/04/2026)
# Generated by AI (claude-sonnet-4-6) in response to cleaning-script prompt
# NOTE: This is the ORIGINAL AI-generated version before human editing
# Key issues found by team and fixed in edited version:
#   1. No handling of special ma_vung codes (Hoang Sa: 00, Truong Sa: 64)
#   2. No NAME_FIX dict for 4+ province names that don't match GeoJSON
#   3. Missing encoding="utf-8" when opening vn_geo.json
#   4. Hard-coded path "data/" instead of project structure "THPT_Dashboard/data/"

import pandas as pd
import glob, os, json

SCORE_COLS = ['toan','ngu_van','ngoai_ngu','vat_ly','hoa_hoc',
              'sinh_hoc','lich_su','dia_ly','gdcd']

# Step 2: Load and concatenate files
dfs = []
for f in sorted(glob.glob("data/thpt*.csv")):
    year = int(os.path.basename(f)[4:8])
    df = pd.read_csv(f)
    df.columns = df.columns.str.lower().str.replace(' ', '_')
    df['nam'] = year
    dfs.append(df)
combined = pd.concat(dfs, ignore_index=True)

# Step 3: Extract province code from first 2 chars of sbd
combined['ma_vung'] = combined['sbd'].astype(str).str[:2]

# Step 4: Merge with province lookup
mavung = pd.read_csv("data/mavung.csv", dtype={'ma_vung': str})
combined = combined.merge(mavung, on='ma_vung', how='left')

# Step 5: Drop all-NaN rows
combined = combined.dropna(subset=SCORE_COLS, how='all')

# Step 6: Cast score columns
for col in SCORE_COLS:
    combined[col] = pd.to_numeric(combined[col], errors='coerce')

# Step 7: Check GeoJSON name match
with open("data/vn_geo.json") as f:   # BUG: missing encoding="utf-8"
    geo = json.load(f)
geo_names = {feat['properties']['NAME_1'] for feat in geo['features']}
combined['geo_match'] = combined['ten_tinh'].isin(geo_names)
print(f"Tỉnh không match GeoJSON: {combined[~combined['geo_match']]['ten_tinh'].unique()}")
# Expected output: ['Bà Rịa - Vũng Tàu', 'Thừa Thiên Huế', 'Đắk Lắk', 'Đắk Nông', ...]

combined.to_parquet("data/cleaned_thpt.parquet", index=False)
